INSERT INTO `error_categories` (`id`, `code`, `name`, `description`, `advice`) VALUES (1,'article_error','Artikel hatası','der/die/das veya ein/eine seçimi yanlış.','İsimleri her zaman artikeliyle birlikte öğren: der Tisch, die Lampe, das Auto.'),
(2,'gender_error','Cinsiyet hatası','İsmin dilbilgisel cinsiyeti yanlış.','Cinsiyet Türkçede yok; kelimeyi artikeliyle ezberle, tahmin etme.'),
(3,'case_error','Hal (Kasus) hatası','Nominativ/Akkusativ/Dativ seçimi yanlış.','Fiilin ve edatın hangi hali istediğini kontrol et.'),
(4,'conjugation_error','Fiil çekimi hatası','Fiil kişiye göre yanlış çekilmiş.','Kişi zamiri ile fiil sonunu birlikte çalış: ich -e, du -st, er -t.'),
(5,'word_order_error','Kelime sırası hatası','Cümlede öğe sırası yanlış.','Ana cümlede fiil her zaman ikinci sırada; yan cümlede sonda.'),
(6,'spelling_error','Yazım hatası','Harf, umlaut veya ß yazımı yanlış.','ä, ö, ü ve ß karakterlerini doğru yaz; ss ile ß aynı değildir.'),
(7,'capitalization_error','Büyük harf hatası','İsim küçük harfle yazılmış.','Almancada bütün isimler büyük harfle başlar.'),
(8,'plural_error','Çoğul hatası','Çoğul biçimi yanlış.','Çoğulu kelimeyle birlikte öğren: der Tisch – die Tische.'),
(9,'vocabulary_recall_error','Kelime hatırlama hatası','Doğru kelime hatırlanamadı.','Bu kelimeyi tekrar kuyruğunda daha sık göreceksin.'),
(10,'preposition_error','Edat hatası','Yanlış edat veya edatın istediği hal yanlış.','Edatı istediği hal ile birlikte öğren: mit + Dativ.'),
(11,'auxiliary_error','Yardımcı fiil hatası','Perfekt için haben/sein seçimi yanlış.','Yer değiştirme ve durum değişimi fiilleri sein alır.'),
(12,'participle_error','Partizip II hatası','Partizip II biçimi yanlış.','Düzenli: ge-...-t, düzensiz: ge-...-en. Düzensizleri liste halinde çalış.'),
(13,'separable_verb_error','Ayrılabilir fiil hatası','Ön ek yanlış yere konmuş.','Ana cümlede ön ek cümlenin sonuna gider: Ich stehe um 7 Uhr auf.'),
(14,'pronoun_error','Zamir hatası','Zamir seçimi veya hali yanlış.','Zamir tablosunu hal ile birlikte çalış: ich/mich/mir.'),
(15,'adjective_ending_error','Sıfat takısı hatası','Sıfatın çekim eki yanlış.','Sıfat çekimi artikel türüne, cinsiyete ve hale bağlıdır.'),
(16,'semantic_error','Anlam hatası','Cevap istenen anlamı karşılamıyor.','Sorunun ne istediğini tekrar oku; kelimenin Türkçe karşılığını kontrol et.');
