INSERT INTO `exercises` (`id`, `lesson_id`, `skill_id`, `vocabulary_id`, `grammar_topic_id`, `exercise_type`, `mode`, `prompt`, `prompt_tr`, `context`, `correct_answer`, `accepted_answers`, `explanation`, `memory_hint`, `cefr_level`, `difficulty`, `variant_group`, `audio_text`, `is_generated`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES (1,1,1,NULL,NULL,'multiple_choice','recognition','Almancada \"J\" harfinin adı nedir?',NULL,NULL,'yot',NULL,'J harfi \"yot\" diye okunur ve kelime içinde \"y\" sesi verir: ja = ya.',NULL,'A0',2,'alphabet-letter',NULL,0,1,0,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(2,1,1,NULL,NULL,'multiple_choice','recognition','\"W\" harfi kelime içinde hangi sesi verir?',NULL,NULL,'v',NULL,'Wasser kelimesi \"vasır\" diye okunur. W = v sesidir.',NULL,'A0',2,'alphabet-sound',NULL,0,1,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(3,1,1,NULL,NULL,'multiple_choice','recognition','\"Z\" harfi kelime içinde hangi sesi verir?',NULL,NULL,'ts',NULL,'zehn kelimesi \"tseen\" okunur. Z = ts sesidir.',NULL,'A0',2,'alphabet-sound',NULL,0,1,2,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(4,1,1,NULL,NULL,'text_input','recall','\"Vater\" kelimesindeki V harfi hangi sesi verir? Tek harfle yaz.',NULL,NULL,'f','[\"F\"]','Almanca kökenli kelimelerde V genellikle \"f\" okunur: Vater = \"fatır\".',NULL,'A0',2,'alphabet-sound',NULL,0,1,3,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(5,1,1,NULL,NULL,'multiple_choice','application','Bir memur adını soruyor. Hangi cümleyle harf harf söylemesini isteyebilirsin?',NULL,NULL,'Können Sie das buchstabieren?',NULL,'buchstabieren = harf harf söylemek. Resmi ortamda bu cümle çok işe yarar.',NULL,'A0',2,'alphabet-use',NULL,0,1,4,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(6,2,3,NULL,NULL,'multiple_choice','recognition','ß harfi hangi durumda kullanılır?',NULL,NULL,'Uzun ünlü veya çift ünlüden sonra',NULL,'Straße: a uzun → ß. Fluss: u kısa → ss.',NULL,'A0',2,'eszett-rule',NULL,0,1,0,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(7,2,2,NULL,NULL,'multiple_choice','recall','Klavyende \"ü\" yoksa doğru yazım hangisidir?',NULL,NULL,'ue',NULL,'Umlautlar ae, oe, ue olarak yazılır. Sadece harfi atmak kelimeyi bozar.',NULL,'A0',2,'umlaut-write',NULL,0,1,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(8,2,2,NULL,NULL,'text_input','spelling','\"kapı\" kelimesinin Almancasını artikeliyle birlikte yaz.',NULL,NULL,'die Tür','[\"die Tuer\"]','die Tür – die Türen. Umlaut atlanırsa kelime anlamını kaybeder.',NULL,'A0',2,'umlaut-write',NULL,0,1,2,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(9,2,2,NULL,NULL,'multiple_choice','recognition','Almanca \"ä\" sesi Türkçedeki hangi sese en yakındır?',NULL,NULL,'e',NULL,'ä sesi Türkçe \"e\" sesine çok yakındır: Väter ≈ \"feter\".',NULL,'A0',2,'umlaut-sound',NULL,0,1,3,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
