INSERT INTO `lessons` (`id`, `module_id`, `slug`, `title`, `cefr_level`, `lesson_type`, `objective`, `summary`, `estimated_minutes`, `completion_threshold`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (1,1,'a0-alfabe','Alman Alfabesi','A0','pronunciation','Almanca 26 harfin adını söyleyebilmek ve kendi adını harf harf söyleyebilmek.','Alfabe, telefonda ad-soyad söylerken ve resmi kurumlarda en çok işine yarayacak temel beceridir.',12,80,0,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(2,1,'a0-umlaut','ä, ö, ü ve ß','A0','pronunciation','Umlaut harflerini tanımak, doğru okumak ve doğru yazmak.','ä, ö, ü ve ß Almancanın dört özel karakteridir. Yanlış yazılırsa kelime anlamı değişebilir.',12,80,1,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(3,1,'a0-ch-sch-sp-st','ch, sch, sp, st','A0','pronunciation','Almancanın en sık geçen harf birleşimlerini doğru okumak.','Bu dört birleşim Almanca kelimelerin çok büyük kısmında geçer. Yanlış okursan hiç anlaşılmazsın.',12,80,2,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(4,1,'a0-diftong','ei, ie, eu, äu','A0','pronunciation','İki ünlü yan yana geldiğinde hangi sesin çıktığını bilmek.','ei ve ie karıştırılırsa kelime tamamen değişir. Bu ders yazım hatalarının yarısını önler.',10,80,3,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(5,1,'a0-sessizler','w, v, j, z, r, h ve ünlü uzunluğu','A0','pronunciation','Türkçe konuşanı en çok yanıltan ünsüzleri doğru çıkarmak ve vurguyu doğru yere koymak.','Bu ders A0 telaffuz bloğunun son parçasıdır. Bundan sonra kelimeleri doğru okuyabileceksin.',12,80,4,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(6,2,'a0-selamlasma','Selamlaşma ve Vedalaşma','A0','vocabulary','Günün saatine ve ortamın resmiyetine göre doğru selamlaşmayı seçmek.','Almanya\'da yanlış selamlaşma kaba görünür. Bu ders hangi kalıbı ne zaman kullanacağını öğretir.',12,80,5,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(7,2,'a0-kendini-tanitma','Kendini Tanıtma','A0','grammar','Adını, memleketini, oturduğun yeri ve mesleğini söyleyebilmek.','Dört cümlelik bir tanıtım, Almanya\'daki ilk haftanda defalarca kullanacağın en değerli bloktur.',14,80,6,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(8,2,'a0-ulke-milliyet','Ülkeler, Milliyetler ve Diller','A0','vocabulary','Ülke, milliyet ve dil adlarını ayırt etmek ve doğru kullanmak.','Almancada ülke, milliyet ve dil üç ayrı kelimedir. Türkçede çoğu zaman aynıdır; bu ders farkı netleştirir.',12,80,7,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(9,2,'a0-sie-du','Sie mi du mu?','A0','grammar','Resmi ve samimi hitabı doğru seçmek ve fiili buna göre çekmek.','Almanya\'da yanlış hitap iş görüşmesini bile etkileyebilir. Bu ders kültürel olarak da kritiktir.',12,80,8,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(10,3,'a0-sayilar-0-20','Sayılar 0-20','A0','vocabulary','0-20 arası sayıları duyduğunda anlamak ve söyleyebilmek.','Fiyat, saat, peron, kapı numarası: günlük hayatın her yerinde sayı var.',10,80,9,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(11,3,'a0-sayilar-21-100','Sayılar 21-100 ve Ters Okuma','A0','grammar','İki basamaklı sayıları Almanca mantığıyla kurmak ve duyduğunda doğru anlamak.','Almanca sayı okuma Türkçenin tersidir. Bu ders anlaşılmadan fiyat ve telefon numarası anlaşılmaz.',12,80,10,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(12,3,'a0-iletisim-bilgileri','Telefon, Adres ve Posta Kodu','A0','daily_life','Telefon numaranı, adresini ve posta kodunu Almanca söyleyebilmek.','Bürgeramt, doktor, işveren: hepsi bu üç bilgiyi sorar. Doğru söylemek zorundasın.',12,80,11,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(13,4,'a0-meslekler','Meslekler','A0','vocabulary','Mesleğini söylemek, karşındakinin mesleğini sormak ve anlamak.','Almanya\'da tanışmanın ikinci cümlesi neredeyse her zaman meslek üzerinedir.',12,80,12,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(14,4,'a0-hayatta-kalma','Anlamadığında Ne Diyeceksin?','A0','daily_life','Anlamadığını kibarca söylemek, tekrar veya yavaşlatma istemek.','Bu ders A0\'ın en pratik dersidir. Bu beş cümle Almanya\'daki ilk ayını kurtarır.',12,80,13,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(15,4,'a0-isim-buyuk-harf','Almancada İsimler Büyük Harfle Yazılır','A0','grammar','İsimleri tanımak ve her zaman büyük harfle yazmak.','Bu kural Almancaya özgüdür ve yazım hatalarının en büyük kaynağıdır.',10,80,14,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(16,5,'a1-zamirler','Kişi Zamirleri','A1','grammar','Altı kişi zamirini tanımak ve fiil çekiminin bunlara bağlı olduğunu kavramak.','Almancada fiil, öznesine göre değişir. Bu yüzden zamirler bütün dilbilgisinin temelidir.',12,80,15,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(17,5,'a1-sein','sein Fiili (Präsens)','A1','grammar','sein fiilini altı kişide doğru çekmek ve kimlik/durum cümleleri kurmak.','sein, Almancanın en sık kullanılan fiilidir ve tamamen düzensizdir. Ezberlenmek zorundadır.',14,80,16,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(18,5,'a1-haben','haben Fiili (Präsens)','A1','grammar','haben fiilini doğru çekmek ve \"var/yok\" anlamını kurmak.','Türkçede \"var\" dediğimiz yerde Almancada çoğu zaman haben kullanılır.',12,80,17,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(19,5,'a1-duzenli-fiiller','Düzenli Fiil Çekimi','A1','grammar','Düzenli fiillerin altı kişideki eklerini otomatik uygulamak.','Almanca fiillerin büyük çoğunluğu bu kalıba uyar. Bir kez öğrenirsen yüzlerce fiili çekebilirsin.',14,80,18,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(20,5,'a1-v2-kurali','V2: Fiil İkinci Sırada','A1','grammar','Ana cümlede çekimli fiili her zaman ikinci pozisyona koymak.','Bu, Almanca cümle yapısının bir numaralı kuralıdır. Bozulursa cümle Alman kulağına yanlış gelir.',14,80,19,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(21,6,'a1-w-fragen','W-Fragen: Soru Kelimeleri','A1','grammar','Soru kelimeleriyle bilgi sorusu kurmak.','Bir ülkeye yeni gelen insanın en çok ihtiyacı olan beceri soru sormaktır.',12,80,20,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(22,6,'a1-ja-nein-fragen','Evet/Hayır Soruları','A1','grammar','Fiili başa alarak evet/hayır sorusu kurmak ve doch kullanımını anlamak.','Almancada evet/hayır sorusu kurmak için ek kelime gerekmez; sadece sıra değişir.',10,80,21,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(23,6,'a1-kok-degistiren-fiiller','Kök Değiştiren Fiiller','A1','grammar','du ve er biçimlerinde kök ünlüsü değişen fiilleri tanımak ve doğru çekmek.','En sık kullanılan fiillerin çoğu bu gruptadır. Ezberlenmeleri şart.',14,80,22,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(24,7,'a1-der-die-das','der / die / das','A1','grammar','Belirli artikelin işlevini kavramak ve kelimeleri artikeliyle öğrenme alışkanlığı kazanmak.','Artikel bilinmeden Akkusativ, Dativ, sıfat çekimi ve ilgi cümlesi öğrenilemez. Burası temeldir.',16,80,23,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(25,7,'a1-ein-eine','ein / eine (Belirsiz Artikel)','A1','grammar','Belirli ve belirsiz artikel arasındaki farkı kullanabilmek.','ein/eine \"bir tane, herhangi biri\" demektir; der/die/das ise \"bilinen, belirli\" demektir.',12,80,24,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(26,7,'a1-cogul','Çoğul Biçimleri','A1','grammar','Beş çoğul grubunu tanımak ve çoğulu kelimeyle birlikte öğrenmek.','Almancada çoğul için tek bir ek yoktur. Beş farklı yol vardır ve kelimeyle birlikte ezberlenir.',14,80,25,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(27,7,'a1-nominativ','Nominativ: Özne Hali','A1','grammar','Cümlenin öznesini bulmak ve Nominativ biçimini tanımak.','Nominativ, sözlükte gördüğün temel biçimdir. Diğer haller bunun üzerine kurulur.',12,80,26,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(28,8,'a1-akkusativ','Akkusativ: Belirtme Hali','A1','grammar','Nesneyi Akkusativ haline koymak ve yalnızca eril artikelin değiştiğini kavramak.','Akkusativ, Almancanın ilk hal konusudur. İyi haber: sadece \"der\" değişir.',16,80,27,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(29,8,'a1-iyelik','İyelik Sıfatları (mein, dein ...)','A1','grammar','İyelik sıfatlarını cinsiyet ve hale göre doğru çekmek.','İyelik sıfatları \"ein\" gibi çekilir. Bir kez öğrenirsen hepsi aynı kalıba uyar.',14,80,28,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(30,9,'a1-nicht','nicht ile Olumsuzlama','A1','grammar','nicht kelimesini cümlede doğru yere koymak.','nicht fiili, sıfatı veya belirli bir ismi olumsuzlar. Yeri değişince anlam değişir.',12,80,29,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(31,9,'a1-kein','kein ile Olumsuzlama','A1','grammar','kein ile nicht arasında doğru seçimi yapmak.','Bu iki kelimeyi karıştırmak A1 seviyesinin en yaygın hatasıdır. Kural aslında çok basittir.',12,80,30,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(32,10,'a1-modal-koennen','können: -ebilmek','A1','grammar','können fiilini çekmek ve modal cümle yapısını kurmak.','Modal fiil cümleye girince ikinci fiil mastar olarak sona gider. Bu kalıp bütün modallerde aynıdır.',14,80,31,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(33,10,'a1-modal-muessen','müssen: zorunluluk','A1','grammar','Zorunluluk anlatmak ve \"müssen nicht\" tuzağından kaçınmak.','müssen nicht \"yasak\" demek değildir; \"gerek yok\" demektir. Bu ayrım çok önemlidir.',12,80,32,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(34,10,'a1-modal-wollen-moechten','wollen ve möchten: istemek','A1','grammar','İstek bildirmek ve kibar biçimi seçmek.','möchten kibar, wollen doğrudandır. Yanlış seçim Almanya\'da kaba görünebilir.',12,80,33,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(35,10,'a1-modal-duerfen-sollen-moegen','dürfen, sollen ve mögen','A1','grammar','İzin, tavsiye/talimat ve hoşlanma anlamlarını ayırmak.','Bu üç modal ile A1 modal seti tamamlanır.',14,80,34,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(36,11,'a1-ayrilabilir-fiiller','Ayrılabilir Fiiller','A1','grammar','Ayrılabilir fiili tanımak ve ön eki doğru yere koymak.','Almancanın en dikkat çekici yapılarından biri. Türkçede benzeri yoktur.',14,80,35,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(37,11,'a1-emir-kipi','Emir Kipi (Imperativ)','A1','grammar','du, ihr ve Sie için emir/rica biçimlerini kurmak.','İş yerinde talimat anlamak ve kibar rica etmek için gereklidir.',12,80,36,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(38,12,'a1-saat','Saat Söyleme','A1','daily_life','Resmi ve günlük saat biçimlerini anlamak ve kullanmak.','Vardiya, randevu, tren: Almanya\'da saat yanlış anlaşılırsa işin bozulur.',14,80,37,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(39,12,'a1-gun-ay-tarih','Günler, Aylar ve Tarihler','A1','daily_life','Gün, ay ve tarih söylemek; doğru edatı seçmek.','Randevu ve sözleşme tarihlerini doğru anlamak için gerekli.',12,80,38,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(40,12,'a1-gunluk-rutin','Günlük Rutinini Anlatma','A1','daily_life','Bir günü sırayla anlatmak; ayrılabilir fiil ve saat bilgisini birleştirmek.','Bu ders şimdiye kadar öğrendiğin her şeyi tek bir metinde birleştirir.',14,80,39,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(41,13,'a1-yiyecek-icecek','Yiyecek ve İçecek','A1','vocabulary','Temel yiyecek/içecek kelimelerini artikeliyle öğrenmek ve alışverişte kullanmak.','Süpermarkette ve kantinde ihtiyaç duyacağın kelimeler.',12,80,40,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(42,13,'a1-restoran','Restoranda','A1','daily_life','Sipariş vermek, hesap istemek ve garsonla iletişim kurmak.','Kalıp cümlelerle bir restoran ziyaretini baştan sona yönetebileceksin.',12,80,41,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(43,13,'a1-alisveris','Alışveriş ve Fiyatlar','A1','daily_life','Fiyat sormak, anlamak ve ödeme yapmak.','Sayı bilgisi burada gerçek hayata dönüşüyor.',12,80,42,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(44,13,'a1-aile-ev','Aile ve Ev','A1','vocabulary','Aile üyelerini ve ev bölümlerini artikeliyle öğrenmek.','Kendini ve yaşadığın yeri anlatmak için gerekli kelimeler.',12,80,43,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(45,14,'a1-sehir-ulasim','Şehir ve Ulaşım','A1','daily_life','Toplu taşıma kelimelerini bilmek ve bilet almak.','Almanya\'da toplu taşıma günlük hayatın merkezindedir.',12,80,44,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(46,14,'a1-yol-tarifi','Yol Sorma ve Tarif Etme','A1','daily_life','Yol sormak ve verilen tarifi anlamak.','Kaybolduğunda kullanacağın kalıplar. Anlamak, konuşmaktan daha önemlidir.',12,80,45,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(47,14,'a1-doktor','Doktor ve Randevu','A1','daily_life','Randevu almak, şikayetini anlatmak ve talimatı anlamak.','Almanya\'da doktora gitmek randevu ile olur. Bu ders sağlığınla ilgilidir.',14,80,46,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(48,15,'a1-ilk-gun','İş Yerinde İlk Gün','A1','workplace','Kendini iş ortamında tanıtmak ve temel soruları sormak.','İlk gün söylediklerin, iş arkadaşlarının sana bakışını belirler.',14,80,47,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(49,15,'a1-hastalik-bildirimi','Hastalık Bildirimi ve İzin İsteme','A1','workplace','Hasta olduğunu bildirmek ve izin talep etmek.','Almanya\'da hastalığı zamanında bildirmek bir yükümlülüktür. Bu ders dil öğretir, hukuki tavsiye vermez.',14,80,48,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(50,16,'a2-dativ','Dativ: Yönelme Hali','A2','grammar','Dativ artikel biçimlerini ezberlemek ve Dativ isteyen fiilleri tanımak.','Akkusativ\'de yalnızca \"der\" değişiyordu. Dativ\'de HEPSİ değişir. Burası dikkat ister.',16,80,49,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(51,16,'a2-dativ-zamirler','Dativ Zamirleri','A2','grammar','mir, dir, ihm gibi Dativ zamirlerini doğru kullanmak.','Günlük konuşmanın çok büyük kısmı bu zamirlerle kurulur.',12,80,50,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(52,16,'a2-akk-dat-ayrimi','Akkusativ mi Dativ mi?','A2','grammar','Bir cümlede hangi öğenin hangi hale gireceğine karar vermek.','Bu ders A2\'nin kilit taşıdır. Doğru karar veremezsen sonraki her konu sorunlu olur.',16,80,51,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(53,17,'a2-dativ-edatlar','Dativ Edatları','A2','grammar','Her zaman Dativ isteyen edatları ezberlemek ve kullanmak.','Bu edatlar günlük dilde çok sık geçer. Hepsi istisnasız Dativ alır.',14,80,52,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(54,17,'a2-akkusativ-edatlar','Akkusativ Edatları','A2','grammar','Her zaman Akkusativ isteyen edatları kullanmak.','Dativ edatlarından sonra bunlar kolay gelecek; sayıları daha az.',12,80,53,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(55,17,'a2-wechselpraepositionen','Wechselpräpositionen: Wo? / Wohin?','A2','grammar','Dokuz değişken edatta hareket olup olmadığına göre hal seçmek.','Almancanın en zarif kurallarından biri: hal, anlamı belirler.',16,80,54,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(56,18,'a2-perfekt-temel','Perfekt: Yapı','A2','grammar','Perfekt cümlesi kurmak ve yardımcı fiil + Partizip II yapısını yerleştirmek.','Almanlar günlük konuşmada geçmişi neredeyse her zaman Perfekt ile anlatır.',16,80,55,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(57,18,'a2-haben-sein-secimi','haben mi sein mi?','A2','grammar','Perfekt için doğru yardımcı fiili seçmek.','Yanlış yardımcı fiil, Almanca konuşan birinin kulağını hemen tırmalar.',14,80,56,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(58,18,'a2-partizip-duzensiz','Düzensiz Partizip II','A2','grammar','En sık kullanılan düzensiz fiillerin üç biçimini ezberlemek.','Düzensiz fiiller azdır ama en sık kullanılanlardır. Ezberleri kaçınılmazdır.',16,80,57,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(59,18,'a2-praeteritum-war-hatte','Präteritum: war ve hatte','A2','grammar','sein ve haben fiillerinin geçmiş zamanını kullanmak.','Bu iki fiil konuşmada bile Perfekt yerine Präteritum ile kullanılır.',12,80,58,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(60,19,'a2-nebensatz-temel','Yan Cümlede Fiil Sonda','A2','grammar','Yan cümle kurmak ve fiili doğru konuma yerleştirmek.','Almancanın ikinci büyük yapı kuralı. Türkçe konuşanlar için aslında tanıdık.',16,80,59,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(61,19,'a2-dass','dass ile Yan Cümle','A2','grammar','Düşünce, bilgi ve görüş aktarmak için dass kullanmak.','Fikir bildirmenin ve dolaylı anlatımın temel yapısı.',12,80,60,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(62,19,'a2-wenn-als','wenn ve als','A2','grammar','Koşul ve zaman bildirirken doğru bağlacı seçmek.','Türkçede ikisi de \"-diğinde\" olur; Almancada seçim kurala bağlıdır.',14,80,61,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(63,19,'a2-baglaclar-genis','obwohl, deshalb, trotzdem, sondern','A2','grammar','Zıtlık ve sonuç bildiren bağlaçları doğru yapıyla kullanmak.','Bu bağlaçlar üç farklı yapı grubuna ayrılır; hangisinin ne yaptığını bilmek gerekir.',14,80,62,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(64,20,'a2-komparativ','Karşılaştırma (Komparativ)','A2','grammar','İki şeyi karşılaştırmak ve düzensiz biçimleri bilmek.','Fiyat, iş, ev karşılaştırırken sürekli ihtiyaç duyacaksın.',12,80,63,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(65,20,'a2-refleksiv','Dönüşlü Fiiller','A2','grammar','Dönüşlü fiilleri ve dönüşlü zamirleri kullanmak.','Almanya\'daki resmi işlemlerin çoğu dönüşlü fiillerle anlatılır: sich anmelden, sich bewerben.',14,80,64,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(66,20,'a2-zu-infinitiv','zu + Infinitiv','A2','grammar','İki fiilli cümlelerde zu kullanımını doğru yapmak.','Modal fiillerden farklı olarak burada \"zu\" gerekir. Ne zaman gerekmediğini de bilmelisin.',12,80,65,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(67,21,'a2-ev-kiralama','Ev Kiralama','A2','daily_life','Ev ilanı okumak, ev sahibiyle konuşmak ve sözleşme kelimelerini anlamak.','Almanya\'da ev bulmak zordur; doğru kelimeleri bilmek büyük avantajdır.',14,80,66,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(68,21,'a2-resmi-kurumlar','Resmi Kurumlar ve Anmeldung','A2','daily_life','Randevu almak, form doldurmak ve memurla iletişim kurmak.','Almanya\'da resmi işlemler randevu ve belge üzerine kuruludur.',14,80,67,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(69,21,'a2-banka-saglik','Banka ve Sağlık Sistemi','A2','daily_life','Hesap açmak, havale yapmak ve sağlık sigortasıyla iletişim kurmak.','Maaş almak için banka hesabı, çalışmak için sağlık sigortası gerekir.',14,80,68,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(70,22,'a2-is-eposta','İş E-postası Yazma','A2','workplace','Resmi bir e-postayı doğru yapıyla yazmak.','Almanya\'da iş iletişiminin büyük kısmı e-posta ile yürür. Yapı standarttır.',16,80,69,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(71,22,'a2-telefon','Telefonda Konuşma','A2','workplace','Telefonda kendini tanıtmak, anlamadığını söylemek ve mesaj bırakmak.','Telefon, dil öğrenenler için en zor beceridir çünkü karşındakini göremezsin.',14,80,70,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(72,23,'b1-sifat-belirli','Belirli Artikelden Sonra Sıfat','B1','grammar','der/die/das sonrası sıfat eklerini doğru vermek.','Bu grup en kolayıdır: neredeyse her yerde -en gelir.',16,80,71,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(73,23,'b1-sifat-belirsiz','Belirsiz Artikelden Sonra Sıfat','B1','grammar','ein/eine/kein/mein sonrası sıfat eklerini vermek.','Burada sıfat, artikelin veremediği bilgiyi taşımak zorundadır.',16,80,72,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(74,23,'b1-sifat-artikelsiz','Artikelsiz Sıfat Çekimi','B1','grammar','Artikel yokken sıfatın artikelin işini üstlendiğini kavramak.','İş ilanlarında, tariflerde ve genel ifadelerde çok sık karşına çıkar.',14,80,73,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(75,24,'b1-relativ-nominativ','İlgi Cümlesi: Nominativ','B1','grammar','İlgi zamiriyle iki cümleyi birleştirmek.','İlgi cümlesi, B1 seviyesinin en görünür işaretidir. Cümlelerin uzunluğunu ve derinliğini artırır.',16,80,74,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(76,24,'b1-relativ-akk-dat','İlgi Cümlesi: Akkusativ ve Dativ','B1','grammar','İlgi zamirini yan cümledeki göreve göre çekmek.','Burada hal bilgisi devreye giriyor. A2\'de öğrendiğin Akkusativ/Dativ ayrımı meyvesini veriyor.',16,80,75,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(77,24,'b1-genitiv','Genitiv Temeli','B1','grammar','Sahiplik bildirmenin resmi biçimini tanımak ve okuyabilmek.','Genitiv resmi yazışmada ve sözleşmelerde sık geçer; konuşmada yerini \"von + Dativ\" alır.',14,80,76,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(78,25,'b1-passiv-praesens','Präsens Passiv','B1','grammar','werden + Partizip II ile edilgen cümle kurmak.','İş talimatları, kurallar ve süreç anlatımları neredeyse hep edilgendir.',16,80,77,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(79,25,'b1-passiv-gecmis','Geçmiş Zamanda Passiv ve lassen','B1','grammar','Geçmiş edilgen biçimleri tanımak ve lassen fiilini kullanmak.','Resmi yazışmada ve rapor dilinde en sık karşılaşacağın yapılar.',14,80,78,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(80,26,'b1-konjunktiv-wuerde','würde + Infinitiv','B1','grammar','Kibar istek ve varsayım cümleleri kurmak.','Bu yapı, Almancada kibar görünmenin en pratik yoludur.',14,80,79,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(81,26,'b1-konjunktiv-haette-waere','hätte, wäre ve modal Konjunktiv','B1','grammar','würde yerine doğrudan Konjunktiv kullanılan fiilleri bilmek.','Bazı fiillerde würde kullanılmaz; kendi Konjunktiv biçimleri vardır.',16,80,80,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(82,27,'b1-um-zu-damit','um ... zu ve damit','B1','grammar','Amaç bildirmek ve doğru yapıyı seçmek.','Neden bir şey yaptığını açıklamanın iki yolu. Seçim özneye bağlıdır.',14,80,81,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(83,27,'b1-zaman-baglaclari','bevor, nachdem, während, seitdem, bis, sobald','B1','grammar','Olayları zaman içinde doğru sıralamak.','İş süreçlerini ve geçmişi anlatırken bu bağlaçlar gerekir.',16,80,82,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(84,27,'b1-ohne-statt-zu','ohne ... zu ve statt ... zu','B1','grammar','Olumsuz eşlik ve alternatif bildirmek.','İki küçük yapı, anlatımını hemen B1 seviyesine taşır.',12,80,83,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(85,28,'b1-tekamolo','TeKaMoLo: Cümle İçi Sıralama','B1','grammar','Cümle ortasındaki öğeleri doğru sırayla dizmek.','Cümlen dilbilgisel olarak doğru olsa bile sıralama yanlışsa doğal duyulmaz.',14,80,84,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(86,28,'b1-fiil-edat','Fiil + Edat Kalıpları','B1','grammar','Fiillerin sabit edatlarını ve bu edatların istediği hali ezberlemek.','Bu kalıplar tahmin edilemez; liste halinde ezberlenir. B1\'in en çok hata yapılan alanı.',16,80,85,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(87,28,'b1-da-wo-bilesikleri','da-/wo- Bileşikleri','B1','grammar','Edat + zamir yerine bileşik biçimleri kullanmak.','Bu yapılar olmadan doğal Almanca konuşmak mümkün değildir.',14,80,86,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(88,28,'b1-n-deklination','n-Deklination','B1','grammar','Nominativ dışında -n/-en alan eril isimleri tanımak.','Küçük bir grup ama çok sık kullanılan isimler. Hata yapılırsa hemen dikkat çeker.',12,80,87,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(89,29,'b1-toplanti','Toplantı Dili','B1','workplace','Toplantıda söz almak, görüş bildirmek ve anlamadığını söylemek.','Toplantıda susan kişi, bilgisiz sanılır. Bu kalıplar konuşmanı sağlar.',16,80,88,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(90,29,'b1-resmi-yazisma','Resmi Yazışma ve Şikayet','B1','workplace','Resmi bir dilekçe veya şikayet mektubu yazmak.','Kurumlarla yazışma Almanya\'da yazılı yapılır ve belli bir kalıbı vardır.',16,80,89,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(91,29,'b1-is-guvenligi','İş Güvenliği ve Sözleşme Kelimeleri','B1','workplace','Güvenlik talimatlarını anlamak ve sözleşme kelimelerini tanımak.','Bu ders dil öğretir. Hukuki durumun için sözleşmene ve yetkili bir danışmana bak.',16,80,90,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(92,30,'b1-okuma','B1 Okuma Anlama','B1','grammar','Gerçek metinleri (ilan, e-posta, talimat) anlamak ve bilgi çıkarmak.','B1 okuma, her kelimeyi anlamak değil, gerekli bilgiyi bulmaktır.',16,80,91,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(93,30,'b1-yazma','B1 Yazma','B1','grammar','Yapılandırılmış, bağlaçlarla örülmüş bir metin üretmek.','B1 yazmada beklenen: net yapı, doğru bağlaçlar ve tutarlı zaman kullanımı.',18,80,92,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(94,30,'b1-konusma-degerlendirme','B1 Konuşma ve Kapsamlı Değerlendirme','B1','grammar','Bir konuda görüş bildirmek, gerekçelendirmek ve B1 hedeflerini bir arada test etmek.','B1 yolunun son dersi. Buradaki mastery, uygulama içi B1 değerlendirmesinin temelini oluşturur.',20,80,93,1,'2026-09-10 12:24:10','2026-09-10 12:24:10');
INSERT INTO `modules` (`id`, `slug`, `cefr_level`, `title`, `description`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES (1,'a0-m1-alfabe-ses','A0','Alfabe ve Sesler','Almanca harfleri tanı, okunuşu doğru öğren. Yanlış öğrenilen ses ileride yanlış yazıma dönüşür.',0,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(2,'a0-m2-tanisma','A0','İlk Tanışma','Selamlaşma, kendini tanıtma, isim ve memleket sorma. Almanya\'daki ilk gününde kullanacağın cümleler.',1,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(3,'a0-m3-sayilar','A0','Sayılar ve İletişim Bilgileri','Sayı söyleme, telefon numarası, adres ve posta kodu. Resmi kurumlarda ilk sorulacak şeyler.',2,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(4,'a0-m4-meslek-kaliplar','A0','Meslek ve Hayatta Kalma Kalıpları','Mesleğini söylemek ve anlamadığında ne diyeceğini bilmek. Almanya\'nın ilk haftası için can simidi.',3,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(5,'a1-m1-temel-cumle','A1','Temel Cümle Kurma','Kişi zamirleri, sein ve haben fiilleri, düzenli fiil çekimi ve Almancanın en önemli kuralı: fiil ikinci sırada.',4,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(6,'a1-m2-sorular','A1','Soru Sorma','W soruları, evet/hayır soruları ve kök değiştiren fiiller.',5,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(7,'a1-m3-artikel','A1','Artikel ve Çoğul','der/die/das, ein/eine ve çoğul biçimleri. Almancanın kalbi burasıdır.',6,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(8,'a1-m4-akkusativ','A1','Akkusativ ve İyelik','Belirtme hali ve iyelik sıfatları. Almancanın ilk gerçek \"hal\" konusu.',7,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(9,'a1-m5-olumsuzluk','A1','Olumsuzluk','nicht ve kein arasındaki farkı kalıcı olarak öğren.',8,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(10,'a1-m6-modal','A1','Modal Fiiller','können, müssen, wollen, möchten, dürfen, sollen, mögen. Günlük hayatın en çok kullanılan yapısı.',9,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(11,'a1-m7-ayrilabilir','A1','Ayrılabilir Fiiller ve Emir Kipi','Ön eki cümlenin sonuna giden fiiller ve istek/emir bildirme.',10,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(12,'a1-m8-zaman','A1','Zaman ve Günlük Rutin','Saat söyleme, gün ve tarih, günlük programını anlatma.',11,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(13,'a1-m9-gunluk-hayat','A1','Günlük Hayat','Yemek, restoran, alışveriş, aile ve ev. Almanya\'da ilk haftanın konuları.',12,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(14,'a1-m10-sehir-saglik','A1','Şehir, Ulaşım ve Sağlık','Yol sormak, toplu taşıma kullanmak ve doktora gitmek.',13,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(15,'a1-m11-is-temelleri','A1','İş Yerinde Temel İletişim','İlk gün, çalışma saatleri, mola, hastalık bildirimi. İş Almancasının başlangıcı.',14,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(16,'a2-m1-dativ','A2','Dativ Hali','Yönelme hali, Dativ zamirleri ve Akkusativ ile ayrımı. A2\'nin en kritik konusu.',15,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(17,'a2-m2-edatlar','A2','Edatlar ve Hal İlişkisi','Dativ edatları, Akkusativ edatları ve Wechselpräpositionen.',16,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(18,'a2-m3-perfekt','A2','Geçmiş Zaman: Perfekt','Konuşma dilinin geçmiş zamanı. Partizip II, haben/sein seçimi ve Präteritum temeli.',17,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(19,'a2-m4-nebensatz','A2','Yan Cümleler','weil, dass, wenn, als, obwohl. Fiilin sona gittiği yapı.',18,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(20,'a2-m5-sifat-refleksiv','A2','Sıfatlar ve Dönüşlü Fiiller','Karşılaştırma, üstünlük ve dönüşlü fiiller.',19,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(21,'a2-m6-gunluk-almanya','A2','Almanya\'da Günlük Hayat','Ev kiralama, resmi kurumlar, banka ve sağlık sistemi.',20,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(22,'a2-m7-is-almancasi','A2','İş Almancası A2','E-posta yazma, telefon görüşmesi ve kibar rica kalıpları.',21,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(23,'b1-m1-sifat-cekimi','B1','Sıfat Çekimi','Sıfatların isimden önce gelirken aldığı ekler. B1\'in en teknik konusu.',22,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(24,'b1-m2-ilgi-cumlesi','B1','İlgi Cümleleri','der, die, das ile kurulan ilgi cümleleri. Cümleleri birleştirmenin yolu.',23,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(25,'b1-m3-passiv','B1','Edilgen Yapı (Passiv)','İşi kimin yaptığı değil, ne yapıldığı önemli olduğunda kullanılan yapı.',24,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(26,'b1-m4-konjunktiv','B1','Konjunktiv II: Kibarlık ve Varsayım','würde, hätte, wäre, könnte. Almanya\'da profesyonel iletişimin dili.',25,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(27,'b1-m5-amac-zaman','B1','Amaç ve Zaman Cümleleri','um...zu, damit, bevor, nachdem, während. Cümleleri anlamlı biçimde bağlama.',26,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(28,'b1-m6-cumle-yapisi','B1','İleri Cümle Yapısı','TeKaMoLo, fiil + edat kalıpları, da-/wo- bileşikleri, n-Deklination ve dolaylı sorular.',27,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(29,'b1-m7-is-dunyasi','B1','İş Dünyası B1','Toplantı dili, resmi yazışma, sorun anlatma, iş güvenliği ve sözleşme kelimeleri.',28,1,'2026-09-10 12:24:10','2026-09-10 12:24:10'),
(30,'b1-m8-beceriler','B1','B1 Becerileri ve Değerlendirme','Okuma, yazma, konuşma becerileri ve kapsamlı B1 değerlendirmesi.',29,1,'2026-09-10 12:24:10','2026-09-10 12:24:10');
INSERT INTO `scenario_options` (`id`, `turn_id`, `text_de`, `quality`, `feedback_tr`, `better_alternative`, `score_clarity`, `score_grammar`, `score_naturalness`, `score_politeness`, `sort_order`) VALUES (1,1,'Guten Morgen! Drei Brötchen, bitte.','good','Mükemmel. Selamlaşma + net sipariş + bitte. Almanya\'da tam beklenen biçim bu.',NULL,5,5,5,5,0),
(2,1,'Hallo. Ich will drei Brötchen.','ok','Anlaşılır ama \"Ich will\" biraz sert durur. Almanya\'da alışverişte \"Ich möchte\" veya doğrudan \"Drei Brötchen, bitte\" tercih edilir.','Ich möchte drei Brötchen, bitte.',5,4,3,2,1),
(3,1,'Drei Brötchen.','ok','Anlaşılır fakat \"bitte\" olmadan biraz kaba durur. Tek kelime büyük fark yaratır.','Drei Brötchen, bitte.',5,4,3,2,2),
(4,1,'Ich habe drei Brötchen.','bad','Bu \"Üç ekmeğim var\" demektir. Sipariş vermek için möchten kullanılır ya da doğrudan miktar söylenir.','Ich möchte drei Brötchen, bitte.',1,2,1,3,3),
(5,2,'Ja, einen Kaffee bitte.','good','Doğru. der Kaffee Akkusativ\'de \"einen Kaffee\" olur.',NULL,5,5,5,5,0),
(6,2,'Ja, ein Kaffee bitte.','ok','Anlaşılır ama hal hatası var. der Kaffee nesne olduğu için \"einen Kaffee\" olmalı.','Ja, einen Kaffee bitte.',5,3,4,5,1),
(7,2,'Nein, danke. Das ist alles.','good','Bu da tamamen doğru bir cevap. \"Das ist alles\" alışverişi kapatmanın standart yoludur.',NULL,5,5,5,5,2),
(8,2,'Ich mag Kaffee.','bad','\"Kahveyi severim\" demek sipariş vermek değildir. Fırıncı ne isteyeceğini soruyor.','Ja, einen Kaffee bitte.',2,4,2,4,3),
(9,3,'Kann ich mit Karte zahlen?','good','Doğru ve kibar. Almanya\'da küçük fırınlarda hâlâ nakit isteyen yerler olduğu için sormak yerinde.',NULL,5,5,5,5,0),
(10,3,'Mit Karte.','ok','Anlaşılır ve pratikte sık kullanılır, ama tam cümle daha kibar durur.','Kann ich mit Karte zahlen?',5,4,4,3,1),
(11,3,'Ich zahle mit die Karte.','ok','Anlam doğru ama hal hatası var: mit her zaman Dativ ister → mit der Karte.','Ich zahle mit der Karte.',4,2,3,4,2),
(12,3,'Ich habe kein Geld.','bad','Bu \"Param yok\" demektir ve istediğin anlam bu değil.','Kann ich mit Karte zahlen?',1,4,2,3,3),
(13,4,'Ja, natürlich. Also um fünf Uhr statt um sechs?','good','Çok iyi. Kabul ediyorsun ve saati teyit ediyorsun. Teyit etmek yanlış anlaşılmayı önler ve profesyonel görünür.',NULL,5,5,5,5,0),
(14,4,'Ja, kein Problem.','ok','Kabul edilebilir ama saati teyit etmedin. İş yerinde saat teyidi her zaman iyi bir alışkanlıktır.','Ja, kein Problem. Also um fünf Uhr?',4,5,5,5,1),
(15,4,'Ja.','ok','Anlaşılır ama çok kısa. Alman iş ortamında kısa cevap soğuk durabilir.','Ja, natürlich. Um wie viel Uhr genau?',4,5,3,3,2),
(16,4,'Nein, ich kann nicht.','bad','Reddetmek hakkın ama gerekçesiz \"hayır\" Alman iş kültüründe kaba durur. Gerekçe eklemek beklenir.','Das ist leider schwierig, weil ich meine Kinder zur Schule bringen muss.',4,5,2,1,3),
(17,5,'Ja, ich fahre mit dem Auto, das geht.','good','Doğru. mit + Dativ (dem Auto) ve net bir onay. Amirin planlama yapabilir.',NULL,5,5,5,5,0),
(18,5,'Ja, ich fahre mit dem Bus. Aber der erste Bus kommt um 4:50.','good','Çok iyi. Kabul ediyorsun ama olası riski de belirtiyorsun. Bu, Almanya\'da beklenen şeffaf iletişimdir.',NULL,5,5,5,5,1),
(19,5,'Ja, ich gehe mit dem Bus.','ok','Anlam anlaşılıyor ama fiil yanlış: araçla gidiliyorsa \"fahren\" kullanılır, \"gehen\" yürümektir.','Ja, ich fahre mit dem Bus.',4,3,3,5,2),
(20,5,'Ich weiß nicht.','bad','Belirsiz cevap iş planlamasını zorlaştırır. Emin değilsen bunu açıkça söyle ve ne zaman teyit edeceğini belirt.','Ich prüfe die Busverbindung und sage Ihnen heute Nachmittag Bescheid.',3,5,3,3,3),
(21,6,'Alles klar, bis morgen. Auf Wiedersehen!','good','Doğru ve doğal. Resmi ortamda \"Auf Wiedersehen\" güvenli seçimdir.',NULL,5,5,5,5,0),
(22,6,'Bis morgen!','good','Kısa ama tamamen uygun. İş arkadaşları arasında yaygındır.',NULL,5,5,5,4,1),
(23,6,'Tschüss!','ok','Anlaşılır fakat amire karşı biraz fazla samimi olabilir. Ekipte \"du\" kullanılıyorsa sorun değildir.','Auf Wiedersehen!',5,5,4,3,2),
(24,6,'Gute Nacht.','bad','\"Gute Nacht\" yalnızca gece yatmadan önce kullanılır. Gündüz vedalaşmak için uygun değildir.','Auf Wiedersehen!',2,5,1,3,3),
(25,7,'Guten Tag, hier ist Emre Yılmaz. Ich möchte einen Termin vereinbaren.','good','Mükemmel. Telefonda \"hier ist + ad\" standart tanıtımdır; randevu için \"einen Termin vereinbaren\" doğru kalıptır.',NULL,5,5,5,5,0),
(26,7,'Hallo, ich brauche einen Termin.','ok','Anlaşılır ama kendini tanıtmadın. Telefonda ad vermek beklenir.','Guten Tag, hier ist Emre Yılmaz. Ich brauche einen Termin.',5,5,3,3,1),
(27,7,'Guten Tag, ich möchte ein Termin machen.','ok','Anlaşılır ama hal hatası var: der Termin → einen Termin.','Guten Tag, ich möchte einen Termin machen.',5,3,4,5,2),
(28,7,'Ich bin krank.','ok','Bilgi doğru ama randevu istediğini söylemedin. Sekreter ne yapacağını bilemez.','Guten Tag, ich bin krank und möchte einen Termin vereinbaren.',3,5,3,4,3),
(29,8,'Nein, ich komme zum ersten Mal. Ich habe Schmerzen im Rücken.','good','Doğru ve eksiksiz. İki soruyu da cevapladın.',NULL,5,5,5,5,0),
(30,8,'Nein. Mein Rücken tut weh.','good','Bu da tamamen doğru. \"wehtun\" günlük dilde çok kullanılır: Mein Rücken tut weh.',NULL,5,5,5,4,1),
(31,8,'Nein, erste Mal. Ich habe Schmerzen in Rücken.','ok','Anlaşılır ama iki küçük hata var: \"zum ersten Mal\" ve \"im Rücken\" (in + dem = im).','Nein, ich komme zum ersten Mal. Ich habe Schmerzen im Rücken.',4,2,3,4,2),
(32,8,'Ich habe Kopfschmerzen.','bad','Bu \"başım ağrıyor\" demektir. Sırt için \"Rückenschmerzen\" veya \"Schmerzen im Rücken\" kullanılır.','Ich habe Rückenschmerzen.',1,5,3,4,3),
(33,9,'Ja, das passt. Was soll ich mitbringen?','good','Çok iyi. Neyi getirmen gerektiğini sormak, ilk ziyarette zaman kaybını önler.',NULL,5,5,5,5,0),
(34,9,'Ja, das passt gut. Vielen Dank.','good','Doğru ve kibar. Yine de sigorta kartını getirmeyi unutma.',NULL,5,5,5,5,1),
(35,9,'Ja. Was ich bringen muss?','ok','Anlaşılır ama kelime sırası yanlış. Soru cümlesinde fiil ikinci sırada olur.','Ja. Was muss ich mitbringen?',4,2,3,4,2),
(36,9,'Nein, ich habe keine Zeit.','bad','Reddetmek hakkın ama alternatif istemeden reddetmek işini çözmez.','Donnerstag passt leider nicht. Haben Sie einen anderen Termin?',3,5,3,3,3),
(37,10,'Guten Tag. Ich möchte mich anmelden.','good','Doğru. sich anmelden dönüşlü bir fiildir; \"mich\" zorunludur.',NULL,5,5,5,5,0),
(38,10,'Guten Tag. Ich möchte anmelden.','ok','Anlaşılır ama dönüşlü zamir eksik: \"Ich möchte mich anmelden.\"','Ich möchte mich anmelden.',4,2,3,5,1),
(39,10,'Guten Tag. Ich habe eine neue Wohnung und muss mich anmelden.','good','Çok iyi. Sebebi de belirtmek memura bağlamı verir.',NULL,5,5,5,5,2),
(40,10,'Ich will Papier.','bad','Bu ne istediğini anlatmıyor. Net bir talep gerekiyor.','Ich möchte mich anmelden.',1,3,1,2,3),
(41,11,'Meinen Ausweis habe ich dabei. Was bedeutet Wohnungsgeberbestätigung genau?','good','Mükemmel. Bildiğini söyleyip bilmediğini sormak en doğru davranış. Memurlar açıklamakla yükümlüdür.',NULL,5,5,5,5,0),
(42,11,'Ja, ich habe alles dabei.','bad','Emin değilsen \"her şey yanımda\" demek risklidir. Belge eksikse randevu boşa gider ve yeni randevu haftalar sürebilir.','Meinen Ausweis habe ich. Was ist eine Wohnungsgeberbestätigung?',3,5,3,4,1),
(43,11,'Ich habe mein Ausweis dabei.','ok','Anlaşılır ama hal hatası var: der Ausweis nesne olduğu için \"meinen Ausweis\" olmalı.','Ich habe meinen Ausweis dabei.',5,3,4,5,2),
(44,11,'Entschuldigung, ich verstehe das Wort nicht. Können Sie es erklären?','good','Çok iyi. Anlamadığını söylemek profesyonelliktir; resmi kurumlarda tamamen normaldir.',NULL,5,5,5,5,3),
(45,12,'Verstanden. Ich bringe die Bestätigung mit. Kann ich einen neuen Termin bekommen?','good','Mükemmel. Sorunu kabul ediyor, çözümü söylüyor ve sonraki adımı istiyorsun.',NULL,5,5,5,5,0),
(46,12,'Okay. Ich komme später wieder.','ok','Anlaşılır ama Almanya\'da çoğu Bürgeramt randevu ile çalışır. Yeni randevu istemek daha güvenlidir.','Kann ich bitte gleich einen neuen Termin vereinbaren?',4,5,4,4,1),
(47,12,'Warum brauchen Sie das? Das ist nicht fair.','bad','Memura karşı çıkmak süreci hızlandırmaz. Belge yasal bir gerekliliktir; itiraz yerine çözüm istemek daha etkilidir.','Verstanden. Wie bekomme ich diese Bestätigung?',4,5,2,1,2),
(48,12,'Wie bekomme ich diese Bestätigung?','good','Çok iyi bir soru. Belgeyi nasıl alacağını öğrenmek en pratik adımdır.',NULL,5,5,5,5,3),
(49,13,'Ja, genau. Ich heiße Emre Yılmaz und ich interessiere mich sehr für die Wohnung.','good','Mükemmel. sich interessieren für + Akkusativ doğru kullanılmış ve kendini tanıtmışsın.',NULL,5,5,5,5,0),
(50,13,'Ja. Ich interessiere mich für die Wohnung.','good','Doğru. İsim eklemek daha da iyi olurdu.',NULL,5,5,4,4,1),
(51,13,'Ja, ich interessiere für die Wohnung.','ok','Dönüşlü zamir eksik: sich interessieren fiilinde \"mich\" zorunludur.','Ja, ich interessiere mich für die Wohnung.',5,2,3,4,2),
(52,13,'Ja, ich will die Wohnung.','ok','Anlaşılır ama \"Ich will\" bu bağlamda fazla doğrudan durur. İlgilendiğini söylemek daha uygun.','Ja, ich interessiere mich sehr für die Wohnung.',5,5,3,2,3),
(53,14,'Was ist in den Nebenkosten enthalten? Sind Heizung und Wasser dabei?','good','Mükemmel soru. Ek giderlerin kapsamı Almanya\'da daireye göre çok değişir; sormak zorunludur.',NULL,5,5,5,5,0),
(54,14,'Was kostet das insgesamt?','ok','Yararlı ama kapsamı sormuyor. Toplam tutar (Warmmiete) 970 euro; asıl soru ek giderlerin neleri içerdiğidir.','Was ist in den Nebenkosten enthalten?',5,5,4,4,1),
(55,14,'Das ist zu teuer.','bad','Doğrudan fiyat eleştirisi görüşmeyi olumsuz başlatır. Önce bilgi topla, sonra karar ver.','Können Sie mir sagen, was in den Nebenkosten enthalten ist?',4,5,3,1,2),
(56,14,'Ich verstehe. Und die Kaution muss ich sofort zahlen?','good','Doğru ve pratik bir soru. Depozito ödeme zamanlaması önemlidir.',NULL,5,5,5,5,3),
(57,15,'Ja, sehr gern. Welche Unterlagen brauchen Sie von mir?','good','Mükemmel. Almanya\'da daire başvurusunda genellikle gelir belgesi ve kimlik istenir; hazırlıklı olmak avantaj sağlar.',NULL,5,5,5,5,0),
(58,15,'Ja. Ich schicke Ihnen die Unterlagen heute noch.','good','Çok iyi. Hızlı hareket etmek rekabetçi konut piyasasında önemlidir.',NULL,5,5,5,5,1),
(59,15,'Ja, ich möchte mich bewerben. Was für Unterlagen?','ok','Anlaşılır. \"Welche Unterlagen brauchen Sie?\" daha akıcı bir sorudur.','Ja, ich möchte mich bewerben. Welche Unterlagen brauchen Sie?',5,4,4,4,2),
(60,15,'Ich denke darüber nach.','ok','Dilbilgisel olarak doğru ve kibar (nachdenken über + Akkusativ → darüber). Ancak yoğun piyasada beklemek daireyi kaybettirebilir.',NULL,5,5,5,4,3),
(61,16,'Es gibt ein Problem mit der Maschine. Sie macht ein komisches Geräusch.','good','Mükemmel. Sorunu net bildiriyor ve belirtiyi tarif ediyorsun. İş güvenliğinde bu doğru davranıştır.',NULL,5,5,5,5,0),
(62,16,'Die Maschine ist kaputt.','ok','Anlaşılır ama kesin bir teşhis koyuyorsun. Emin değilsen belirtiyi tarif etmek daha doğru.','Die Maschine macht ein komisches Geräusch. Ich bin nicht sicher, was los ist.',4,5,4,4,1),
(63,16,'Es gibt ein Problem mit die Maschine.','ok','Anlam doğru ama hal hatası var: mit her zaman Dativ ister → mit der Maschine.','Es gibt ein Problem mit der Maschine.',5,2,4,5,2),
(64,16,'Nichts, alles gut.','bad','Sorunu bildirmemek iş güvenliği açısından ciddi risktir. Şüphelendiğin her durumu bildirmelisin.','Es gibt ein Problem mit der Maschine.',1,5,3,3,3),
(65,17,'Seit ungefähr einer halben Stunde.','good','Doğru. seit + Dativ; \"einer halben Stunde\" tam doğru biçim.',NULL,5,5,5,5,0),
(66,17,'Seit eine halbe Stunde.','ok','Anlaşılır ama seit Dativ ister: seit einer halben Stunde.','Seit einer halben Stunde.',5,2,3,5,1),
(67,17,'Vor einer halben Stunde hat es angefangen.','good','Bu da tamamen doğru ve doğal bir cevap: \"vor + Dativ\" olayın başlangıcını bildirir.',NULL,5,5,5,5,2),
(68,17,'Ich weiß nicht.','ok','Dürüst ama işe yaramaz. Tam bilmiyorsan bile tahmini bir süre vermek bakım ekibine yardımcı olur.','Ich bin nicht sicher, aber ich habe es vor etwa 30 Minuten bemerkt.',3,5,4,4,3),
(69,18,'Ja, ich habe sie sofort ausgeschaltet. Was soll ich jetzt machen?','good','Mükemmel. Doğru davranış + sonraki adımı sorma. Partizip \"ausgeschaltet\" da doğru.',NULL,5,5,5,5,0),
(70,18,'Ja, ich habe sie ausgeschaltet.','good','Doğru. Sonraki adımı sormak daha da iyi olurdu.',NULL,5,5,5,4,1),
(71,18,'Ja, ich habe sie ausschalten.','ok','Partizip biçimi yanlış: ausschalten → ausgeschaltet.','Ja, ich habe sie ausgeschaltet.',5,2,3,5,2),
(72,18,'Nein, sie läuft noch.','bad','Arızalı bir makineyi çalışır durumda bırakmak tehlikelidir. Şüphelendiğinde önce durdur, sonra bildir.','Nein, soll ich sie sofort ausschalten?',5,5,3,2,3);
INSERT INTO `scenario_turns` (`id`, `scenario_id`, `step`, `speaker_de`, `speaker_tr`, `instruction_tr`, `hint`) VALUES (1,1,1,'Guten Morgen! Was darf es sein?','Günaydın! Ne arzu edersiniz?','Selam ver ve üç adet Brötchen iste.','Guten Morgen + ... Brötchen, bitte.'),
(2,1,2,'Gerne. Sonst noch etwas?','Memnuniyetle. Başka bir şey?','Bir de kahve iste.','einen Kaffee (der Kaffee → Akkusativ: einen)'),
(3,1,3,'Das macht vier Euro zwanzig.','Dört euro yirmi sent ediyor.','Kartla ödemek istediğini söyle.','mit Karte zahlen'),
(4,2,1,'Können Sie morgen eine Stunde früher kommen?','Yarın bir saat erken gelebilir misiniz?','Kabul et ve saat kaçta geleceğini teyit et.','Ja, natürlich. + saat teyidi'),
(5,2,2,'Genau, um fünf Uhr. Schaffen Sie das?','Aynen, saat beşte. Yetiştirebilir misiniz?','Yetiştirebileceğini söyle ve toplu taşıma durumunu belirt.','mit dem Bus / mit dem Auto + fahren'),
(6,2,3,'Sehr gut. Dann bis morgen um fünf.','Çok iyi. O zaman yarın beşte görüşürüz.','Vedalaş.','Resmi ortamda uygun veda kalıbı'),
(7,3,1,'Praxis Dr. Bauer, guten Tag. Was kann ich für Sie tun?','Dr. Bauer muayenehanesi, iyi günler. Sizin için ne yapabilirim?','Kendini tanıt ve randevu istediğini söyle.','Guten Tag, hier ist ... + einen Termin'),
(8,3,2,'Waren Sie schon einmal bei uns? Und was haben Sie für Beschwerden?','Daha önce bize geldiniz mi? Şikayetiniz nedir?','İlk kez geldiğini ve sırtının ağrıdığını söyle.','zum ersten Mal + Schmerzen im Rücken'),
(9,3,3,'Wir hätten am Donnerstag um 14:30 Uhr einen Termin frei. Passt das?','Perşembe 14:30\'da boş bir randevumuz var. Uygun mu?','Kabul et ve ne getirmen gerektiğini sor.','Was soll ich mitbringen? / Versichertenkarte'),
(10,4,1,'Guten Tag. Wie kann ich Ihnen helfen?','İyi günler. Size nasıl yardımcı olabilirim?','Kayıt yaptırmak istediğini söyle.','sich anmelden (dönüşlü fiil)'),
(11,4,2,'Haben Sie die Wohnungsgeberbestätigung und Ihren Ausweis dabei?','Ev sahibi onay belgesi ve kimliğiniz yanınızda mı?','Kimliğinin yanında olduğunu söyle, ama belgeyi anlamadıysan sor.','Was bedeutet ...? / Ich habe ... dabei'),
(12,4,3,'Das ist eine Bestätigung von Ihrem Vermieter, dass Sie dort wohnen. Ohne die Bestätigung können wir Sie leider nicht anmelden.','Bu, ev sahibinizin orada oturduğunuzu onayladığı bir belgedir. Bu belge olmadan maalesef kaydınızı yapamıyoruz.','Belgeyi getireceğini söyle ve yeni randevu iste.','Ich bringe ... mit / einen neuen Termin'),
(13,5,1,'Guten Tag. Sie interessieren sich für die Wohnung, richtig?','İyi günler. Daireyle ilgileniyorsunuz, doğru mu?','Onayla ve kendini kısaca tanıt.','sich interessieren für + Akkusativ'),
(14,5,2,'Die Kaltmiete beträgt 780 Euro, dazu kommen 190 Euro Nebenkosten. Die Kaution sind drei Kaltmieten.','Çıplak kira 780 euro, buna 190 euro ek gider ekleniyor. Depozito üç aylık çıplak kira.','Ek giderlerin neleri kapsadığını sor.','Was ist in den Nebenkosten enthalten?'),
(15,5,3,'Heizung und Wasser sind enthalten, Strom müssen Sie selbst anmelden. Möchten Sie sich bewerben?','Isınma ve su dahil, elektriği kendiniz kaydettirmelisiniz. Başvurmak ister misiniz?','İlgilendiğini belirt ve hangi belgeleri getirmen gerektiğini sor.','Welche Unterlagen brauchen Sie?'),
(16,6,1,'Ja, was gibt es?','Evet, ne var?','Makinede bir sorun olduğunu bildir.','Es gibt ein Problem mit + Dativ'),
(17,6,2,'Seit wann ist das so?','Ne zamandır böyle?','Yaklaşık yarım saattir olduğunu söyle.','seit + Dativ (seit einer halben Stunde)'),
(18,6,3,'Gut, dass Sie es gemeldet haben. Haben Sie die Maschine ausgeschaltet?','Bildirmeniz iyi oldu. Makineyi kapattınız mı?','Kapattığını söyle ve ne yapman gerektiğini sor.','ausschalten (ayrılabilir) + Was soll ich jetzt machen?');
INSERT INTO `scenarios` (`id`, `slug`, `title`, `cefr_level`, `category`, `setting_tr`, `role_user`, `role_partner`, `sort_order`, `is_active`) VALUES (1,'baeckerei','Fırında Alışveriş','A1','daily','Sabah saat 7. Mahalledeki fırındasın ve kahvaltı için ekmek almak istiyorsun.','Müşteri','Fırıncı',0,1),
(2,'arbeit-erste-woche','İş Yerinde: Amirin Erken Gelmeni İstiyor','A2','workplace','İş yerinde ilk haftandasın. Amirin yanına geliyor ve yarın için bir istekte bulunuyor.','Çalışan','Amir',1,1),
(3,'arzttermin','Doktordan Randevu Alma','A2','health','Sırtın ağrıyor. Aile hekiminin muayenehanesini arıyorsun.','Hasta','Muayenehane sekreteri',2,1),
(4,'buergeramt-anmeldung','Bürgeramt: İkamet Kaydı','A2','authority','Almanya\'da yeni bir daireye taşındın. Bürgeramt\'ta ikamet kaydı yaptırıyorsun.','Başvuru sahibi','Memur',3,1),
(5,'wohnungsbesichtigung','Daire Görme Randevusu','B1','daily','Bir daire ilanı için ev sahibiyle görüşüyorsun. Daireyi görmeye geldin.','Kiracı adayı','Ev sahibi',4,1),
(6,'problem-melden','İş Yerinde Sorun Bildirme','B1','workplace','Kullandığın makine tuhaf ses çıkarıyor. Amirine bildirmen gerekiyor.','Çalışan','Vardiya amiri',5,1);
