INSERT INTO `vocabulary` (`id`, `german`, `normalized_german`, `article`, `gender`, `plural`, `turkish`, `part_of_speech`, `pronunciation`, `ipa`, `cefr_level`, `topic`, `example_de`, `example_tr`, `usage_notes`, `memory_tip`, `similar_word_note`, `separable_prefix`, `auxiliary`, `preterite`, `participle_ii`, `third_person`, `is_irregular`, `is_reflexive`, `requires_case`, `required_preposition`, `is_active`, `created_at`, `updated_at`) VALUES (1,'Hallo','hallo',NULL,NULL,NULL,'merhaba','phrase','ha-LO',NULL,'A0','begrussung','Hallo, ich heiße Emre.','Merhaba, benim adım Emre.','Her saatte ve hem samimi hem yarı resmi kullanılır.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,NULL,NULL,1,'2026-09-10 12:24:09','2026-09-10 12:24:09'),
(2,'Guten Morgen','guten morgen',NULL,NULL,NULL,'günaydın','phrase','GU-ten MOR-gın',NULL,'A0','begrussung','Guten Morgen, Herr Wagner!','Günaydın, Bay Wagner!','Sabah saat 11 civarına kadar kullanılır.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,NULL,NULL,1,'2026-09-10 12:24:09','2026-09-10 12:24:09'),
(3,'Guten Tag','guten tag',NULL,NULL,NULL,'iyi günler','phrase','GU-ten TAAK',NULL,'A0','begrussung','Guten Tag, wie geht es Ihnen?','İyi günler, nasılsınız?','Resmi ortamda en güvenli selamlaşmadır.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,NULL,NULL,1,'2026-09-10 12:24:09','2026-09-10 12:24:09'),
(4,'Guten Abend','guten abend',NULL,NULL,NULL,'iyi akşamlar','phrase','GU-ten AA-bınt',NULL,'A0','begrussung','Guten Abend, mein Name ist Ayşe Yılmaz.','İyi akşamlar, adım Ayşe Yılmaz.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,NULL,NULL,1,'2026-09-10 12:24:09','2026-09-10 12:24:09'),
(5,'Gute Nacht','gute nacht',NULL,NULL,NULL,'iyi geceler','phrase','GU-tı NAHT',NULL,'A0','begrussung','Gute Nacht, bis morgen!','İyi geceler, yarın görüşürüz!','Yalnızca yatmadan önce vedalaşırken kullanılır, selamlaşmak için değil.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,NULL,NULL,1,'2026-09-10 12:24:09','2026-09-10 12:24:09'),
(6,'Tschüss','tschuess',NULL,NULL,NULL,'hoşça kal','phrase','ÇÜS',NULL,'A0','begrussung','Tschüss, bis später!','Hoşça kal, sonra görüşürüz!','Samimi vedalaşma. Resmi ortamda \"Auf Wiedersehen\" tercih edilir.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,NULL,NULL,1,'2026-09-10 12:24:09','2026-09-10 12:24:09'),
(7,'Auf Wiedersehen','auf wiedersehen',NULL,NULL,NULL,'hoşça kalın, güle güle','phrase','auf VII-der-zee-ın',NULL,'A0','begrussung','Auf Wiedersehen, Frau Meier.','Hoşça kalın, Bayan Meier.','Resmi veda. Telefonda \"Auf Wiederhören\" denir.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,NULL,NULL,1,'2026-09-10 12:24:09','2026-09-10 12:24:09'),
(8,'Bis bald','bis bald',NULL,NULL,NULL,'yakında görüşürüz','phrase','bis BALT',NULL,'A0','begrussung','Bis bald!','Yakında görüşürüz!',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,NULL,NULL,1,'2026-09-10 12:24:09','2026-09-10 12:24:09'),
(9,'Bis morgen','bis morgen',NULL,NULL,NULL,'yarın görüşürüz','phrase',NULL,NULL,'A0','begrussung','Bis morgen im Büro!','Yarın ofiste görüşürüz!',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,NULL,NULL,1,'2026-09-10 12:24:09','2026-09-10 12:24:09'),
(10,'bitte','bitte',NULL,NULL,NULL,'lütfen; rica ederim','particle','Bİ-tı',NULL,'A0','hoeflichkeit','Einen Kaffee, bitte.','Bir kahve, lütfen.','Hem \"lütfen\" hem de teşekküre cevap olarak \"rica ederim\" anlamına gelir.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,NULL,NULL,1,'2026-09-10 12:24:09','2026-09-10 12:24:09'),
(11,'danke','danke',NULL,NULL,NULL,'teşekkürler','particle','DAN-kı',NULL,'A0','hoeflichkeit','Danke für die Hilfe!','Yardım için teşekkürler!',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,NULL,NULL,1,'2026-09-10 12:24:09','2026-09-10 12:24:09'),
(12,'Danke schön','danke schoen',NULL,NULL,NULL,'çok teşekkürler','phrase',NULL,NULL,'A0','hoeflichkeit','Danke schön, das ist sehr nett.','Çok teşekkürler, bu çok nazik.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,NULL,NULL,1,'2026-09-10 12:24:09','2026-09-10 12:24:09'),
(13,'Entschuldigung','entschuldigung','die','f','die Entschuldigungen','özür dilerim; affedersiniz','noun','ent-ŞUL-di-gung',NULL,'A0','hoeflichkeit','Entschuldigung, wo ist der Bahnhof?','Affedersiniz, tren garı nerede?',NULL,'Hem özür hem de birine seslenmek için kullanılır.',NULL,NULL,NULL,NULL,NULL,NULL,0,0,NULL,NULL,1,'2026-09-10 12:24:09','2026-09-10 12:24:09'),
