INSERT INTO `vocabulary_examples` (`id`, `vocabulary_id`, `de`, `tr`, `note`, `sort_order`) VALUES (1,1,'Hallo, ich heiße Emre.','Merhaba, benim adım Emre.',NULL,0),
(2,2,'Guten Morgen, Herr Wagner!','Günaydın, Bay Wagner!',NULL,0),
(3,3,'Guten Tag, wie geht es Ihnen?','İyi günler, nasılsınız?',NULL,0),
(4,4,'Guten Abend, mein Name ist Ayşe Yılmaz.','İyi akşamlar, adım Ayşe Yılmaz.',NULL,0),
(5,5,'Gute Nacht, bis morgen!','İyi geceler, yarın görüşürüz!',NULL,0),
(6,6,'Tschüss, bis später!','Hoşça kal, sonra görüşürüz!',NULL,0),
(7,7,'Auf Wiedersehen, Frau Meier.','Hoşça kalın, Bayan Meier.',NULL,0),
(8,8,'Bis bald!','Yakında görüşürüz!',NULL,0),
(9,9,'Bis morgen im Büro!','Yarın ofiste görüşürüz!',NULL,0),
(10,10,'Einen Kaffee, bitte.','Bir kahve, lütfen.',NULL,0),
(11,11,'Danke für die Hilfe!','Yardım için teşekkürler!',NULL,0),
(12,12,'Danke schön, das ist sehr nett.','Çok teşekkürler, bu çok nazik.',NULL,0),
(13,13,'Entschuldigung, wo ist der Bahnhof?','Affedersiniz, tren garı nerede?',NULL,0),
(14,14,'Ja, das stimmt.','Evet, doğru.',NULL,0),
(15,15,'Nein, danke.','Hayır, teşekkürler.',NULL,0),
(16,16,'Vielleicht komme ich morgen.','Belki yarın gelirim.',NULL,0),
(17,17,'Ja, gern!','Evet, memnuniyetle!',NULL,0),
(18,18,'Mein Name ist Emre.','Benim adım Emre.',NULL,0),
(19,19,'Mein Vorname ist Ayşe.','Ön adım Ayşe.',NULL,0),
(20,20,'Wie ist Ihr Nachname?','Soyadınız nedir?',NULL,0),
(21,21,'Guten Tag, Herr Wagner.','İyi günler, Bay Wagner.',NULL,0),
(22,22,'Frau Meier arbeitet hier.','Bayan Meier burada çalışıyor.',NULL,0),
(23,23,'Aus welchem Land kommst du?','Hangi ülkeden geliyorsun?',NULL,0),
(24,24,'Berlin ist eine große Stadt.','Berlin büyük bir şehir.',NULL,0),
(25,25,'Ich arbeite in Deutschland.','Almanya\'da çalışıyorum.',NULL,0),
(26,26,'Ich komme aus der Türkei.','Türkiye\'den geliyorum.',NULL,0),
(27,27,'Wien liegt in Österreich.','Viyana Avusturya\'dadır.',NULL,0),
(28,28,'Er wohnt in der Schweiz.','O İsviçre\'de yaşıyor.',NULL,0),
(29,29,'Ich lerne Deutsch.','Almanca öğreniyorum.',NULL,0),
(30,30,'Meine Muttersprache ist Türkisch.','Ana dilim Türkçe.',NULL,0),
(31,31,'Sprechen Sie Englisch?','İngilizce konuşuyor musunuz?',NULL,0),
(32,32,'Er ist Türke.','O Türk.',NULL,0),
(33,33,'Sie ist Türkin.','O Türk.',NULL,0),
(34,34,'Sie ist Deutsche.','O Alman.',NULL,0),
(35,35,'Er ist Deutscher.','O Alman.',NULL,0),
(36,36,'Was sind Sie von Beruf?','Mesleğiniz nedir?',NULL,0),
(37,37,'Ich suche Arbeit.','İş arıyorum.',NULL,0),
(38,38,'Er ist Arbeiter in einer Fabrik.','O bir fabrikada işçi.',NULL,0),
(39,39,'Mein Bruder ist Lehrer.','Kardeşim öğretmen.',NULL,0),
(40,40,'Frau Klein ist Lehrerin.','Bayan Klein öğretmen.',NULL,0),
(41,41,'Der Arzt ist sehr freundlich.','Doktor çok güler yüzlü.',NULL,0),
(42,42,'Meine Ärztin heißt Frau Bauer.','Doktorumun adı Bayan Bauer.',NULL,0),
